import * as capacity from '@okikio/capacity';
const host = capacity.create({ browsers: 2, uploads: 4 });
const lease = await capacity.acquire(host, { browsers: 1, uploads: 3 });
try {
  console.log(JSON.stringify(capacity.available(host)));
} finally {
  lease.release();
}
console.log(JSON.stringify(capacity.available(host)));
